<script lang="ts">
 import {SegmentedControl} from '@valar/svelte-ui/segmented-control';
 import SectionTitle from './SectionTitle.svelte';
 import ProviderMark from './ProviderMark.svelte';
 import CompareSourceButton from './CompareSourceButton.svelte';
 import {canCompare,statisticsCopy,valueOf,type StatisticsDay,type StatisticsSource,type StatisticsChartProps} from '../../statisticsData';
 import '../../preview/statistics-compare.css';
 let {view,measure,language,variant,selected,onSelect}:StatisticsChartProps=$props();
 let scale=$state('shared');const scaleId=$props.id();
 const copy=$derived(statisticsCopy(language)),selectedSource=$derived(view.sources.find(source=>source.key===selected));
 function deltaText(value:number){return `${value>0?'+':value<0?'−':''}${copy.format(Math.abs(value),measure,false)}`;}
 function extent(values:(number|null)[]){const known=values.filter((value):value is number=>value!==null);return known.length?Math.max(0,...known):null;}
 function completeDays(days:StatisticsDay[]){return days.length===view.length&&days.every(day=>day.records>0&&!day.incomplete&&valueOf(day,measure)!==null&&(measure==='tokens'||!day.partial));}
 function comparisonIssue(){
  if(view.days.length!==view.previousDays.length||view.days.length!==view.length)return copy.tr('Periods have different lengths. No change is calculated.');
  if(!view.total.records||!view.previous.records)return copy.tr('One period has no records. Unknown is not zero; no change is inferred.');
  if(view.covered<view.length||view.previousCovered<view.length)return copy.tr('Some dates are missing. Only recorded values are shown; gaps are not filled with zero and no change is inferred.');
  if(measure==='cost'&&(!view.costComplete||view.previous.knownCosts<view.previous.records))return copy.tr('Costs are incomplete. Only known amounts are shown; no difference is calculated and unknown does not mean free.');
  if(!canCompare(view,measure))return copy.tr('Records are incomplete. No increase or decrease is inferred.');return null;
 }
 function sourcePair(source:StatisticsSource){const current=valueOf(source,measure),previous=valueOf(source.previous,measure),comparable=canCompare(view,measure)&&completeDays(source.days)&&completeDays(source.previousDays);return {current,previous,delta:comparable&&current!==null&&previous!==null?current-previous:null};}
 const issue=$derived(comparisonIssue()),pairs=$derived(view.sources.map(source=>({source,...sourcePair(source)})));
 const maximum=$derived(extent(view.sources.flatMap(source=>[valueOf(source,measure),valueOf(source.previous,measure)])));
 const sharedMax=$derived(extent(view.sources.flatMap(source=>[...source.days,...source.previousDays].map(day=>valueOf(day,measure)))));
 const x=(value:number)=>8+value/(maximum||1)*224;
 function trendMaximum(source:StatisticsSource){return scale==='shared'?sharedMax:extent([...source.days,...source.previousDays].map(day=>valueOf(day,measure)));}
 const trendX=(at:number)=>view.length===1?120:6+at/(view.length-1)*228;
 const trendY=(value:number,max:number|null)=>70-value/(max||1)*62;
 function trendPath(values:(number|null)[],max:number|null){return values.map((value,at)=>value===null?'':`${at===0||values[at-1]===null?'M':'L'}${trendX(at)},${trendY(value,max)}`).filter(Boolean).join(' ');}
 type WaterStep={key:string;name:string;from:number;to:number;delta:number;source?:StatisticsSource};
 function reconciles(actual:number,expected:number,operations:number,magnitude=Math.max(Math.abs(actual),Math.abs(expected))){return Math.abs(actual-expected)<=Number.EPSILON*Math.max(1,operations)*magnitude*4;}
 const water=$derived.by(()=>{
  const current=valueOf(view.total,measure),previous=valueOf(view.previous,measure);let problem=issue;
  if(!problem&&pairs.some(pair=>pair.delta===null))problem=copy.tr('Some sources have incomplete records. The total difference is not broken down.');
  const operations=Math.max(view.total.records,view.previous.records)+pairs.length;
  if(!problem){const sourcePrevious=pairs.reduce((sum,pair)=>sum+pair.previous!,0),sourceCurrent=pairs.reduce((sum,pair)=>sum+pair.current!,0);if(previous===null||current===null||!reconciles(sourcePrevious,previous,operations)||!reconciles(sourceCurrent,current,operations))problem=copy.tr('Source records do not reconcile with the period totals. The difference is not broken down.');}
  const steps:WaterStep[]=[];
  if(!problem){let running=previous!;steps.push({key:'previous',name:copy.tr('Previous'),from:0,to:running,delta:running});pairs.forEach(({source,delta})=>{steps.push({key:source.key,name:source.name,from:running,to:running+delta!,delta:delta!,source});running+=delta!;});const magnitude=Math.abs(previous!)+pairs.reduce((sum,pair)=>sum+Math.abs(pair.delta!),0);if(!reconciles(running,current!,operations,Math.max(magnitude,Math.abs(current!))))problem=copy.tr('Source records do not reconcile with the period totals. The difference is not broken down.');steps.push({key:'current',name:copy.tr('Current'),from:0,to:current!,delta:current!});}
  const peak=Math.max(0,...steps.flatMap(step=>[step.from,step.to]));return {issue:problem,steps,peak,ceiling:peak*1.14,net:problem?null:current!-previous!};
 });
 const percent=(value:number)=>value/(water.ceiling||1)*100;
</script>
{#snippet periodTotals()}
 <dl class="tp-compare-totals">{#each ['previous','current'] as period}{@const prior=period==='previous'}{@const item=prior?view.previous:view.total}{@const value=valueOf(item,measure)}{@const bounds=prior?view.priorBounds:view.bounds}{@const partial=value!==null&&((prior?view.previousPartial:view.partial)||measure==='cost'&&item.knownCosts<item.records)}{@const dates=bounds.start===bounds.end?copy.shortDate(bounds.start):`${copy.shortDate(bounds.start)}–${copy.shortDate(bounds.end)}`}
  <div><dt><i class={`tp-compare-dot ${prior?'is-prior':'is-current'}`} aria-hidden="true"></i>{copy.tr(prior?'Previous Period':'Current Period')}<span>{dates}</span></dt><dd data-testid={prior?undefined:'hero-total'} data-value={prior?undefined:(value??'unknown')}>{copy.format(value,measure,false)}{#if partial}<small>{copy.tr('Recorded Portion Only')}</small>{/if}</dd></div>
 {/each}</dl>
{/snippet}
{#snippet pairValues(source:StatisticsSource)}
 <span class="tp-compare-values">{#each ['current','previous'] as period}{@const prior=period==='previous'}{@const item=prior?source.previous:source}{@const days=prior?source.previousDays:source.days}{@const value=valueOf(item,measure)}{@const partial=value!==null&&(days.some(day=>!day.records||day.incomplete)||measure==='cost'&&item.knownCosts<item.records)}<span class="tp-compare-value"><span class="tp-compare-sr-only">{copy.tr(prior?'Previous Period':'Current Period')} </span><i class={`tp-compare-dot ${prior?'is-prior':'is-current'}`} aria-hidden="true"></i><span><b>{copy.format(value,measure,false)}</b>{#if partial}<small>{copy.tr('Recorded Portion Only')}</small>{/if}</span></span>{/each}</span>
{/snippet}
{#snippet graphic(step:WaterStep,index:number)}
 <span class="tp-compare-step-space" aria-hidden="true" data-from={step.from} data-to={step.to} data-delta={step.delta}><i class={`tp-compare-water-bar${step.key==='previous'?' is-prior-total':''}${step.key==='current'?' is-current-total':''}${step.delta===0?' is-zero':''}`} style={`bottom:${percent(Math.min(step.from,step.to))}%;height:${percent(Math.abs(step.to-step.from))}%`}></i>{#if index<water.steps.length-1}<i class="tp-compare-water-connector" style={`bottom:${percent(step.to)}%`}></i>{/if}{#if step.source}<b class="tp-compare-water-sign" style={`bottom:calc(${percent(Math.max(step.from,step.to))}% + 5px)`}>{step.delta>0?'+':step.delta<0?'−':'='}</b>{/if}</span><span class="tp-compare-step-label">{step.source?index.toLocaleString(language,{minimumIntegerDigits:2}):step.name}</span>
{/snippet}
<section class={`tp-compare tp-compare-d${variant+1}`} aria-label={copy.tr(variant===0?'Paired Comparison':variant===1?'Parallel Trends':'Change Breakdown')}>
 <SectionTitle>{copy.tr(variant===0?'Paired Comparison':variant===1?'Parallel Trends':'Change Breakdown')}{#snippet aside()}{copy.tr('%@-Day Period · %@',view.length.toLocaleString(language),copy.unit(measure))}{/snippet}</SectionTitle>
 {#if variant===0}
  {@render periodTotals()}<p class="tp-compare-context">{issue??copy.tr('A shared scale shows the difference between each source’s two periods.')}</p><div class="tp-compare-dumbbell-head" aria-hidden="true"><span class="tp-compare-ruler"><span>{(0).toLocaleString(language)}</span><span>{maximum===null?copy.tr('Scale Unknown'):copy.format(maximum,measure)}</span></span><span>{copy.tr('Exact Period Totals')}</span></div>
  <div class="tp-compare-dumbbells" data-source-list role="group" aria-label={copy.tr('Paired source comparisons. Arrow keys browse; Enter or Space opens details.')}>{#each pairs as {source,current,previous,delta} (source.key)}<CompareSourceButton {source} {selected} {onSelect} class="tp-compare-dumbbell-row"><span class="tp-compare-source-name"><ProviderMark {source}/><strong>{source.name}</strong></span><span class="tp-compare-difference" data-delta={delta??'unknown'}>{delta===null?copy.tr('Not Compared'):delta===0?copy.tr('Same in Both Periods'):deltaText(delta)}</span><svg class="tp-compare-dumbbell" viewBox="0 0 240 44" aria-hidden="true"><path d="M8 22H232 M8 17V27 M120 19V25 M232 17V27" class="tp-compare-grid-line"/>{#if delta!==null}<line x1={x(previous!)} x2={x(current!)} y1="22" y2="22" class="tp-compare-join"/>{/if}{#if previous!==null}<circle cx={x(previous)} cy="22" r="5" class="tp-compare-prior-point"/>{/if}{#if current!==null}<circle cx={x(current)} cy="22" r="3.3" class="tp-compare-current-point"/>{/if}</svg>{@render pairValues(source)}</CompareSourceButton>{/each}</div>
  <p class="tp-chart-note">{copy.tr('Filled points are current; hollow points are previous. Every source shares a scale starting at zero.')} {copy.tr(issue?'Incomplete periods are not connected.':'Connections show differences, not good or bad outcomes.')} {copy.tr('Arrow keys browse sources. Enter, Space, or a click opens details.')}</p>
 {:else if variant===1}
  {@render periodTotals()}<div class="tp-compare-scale-control" aria-describedby={scaleId}><SegmentedControl label={copy.tr('Trend Vertical Scale')} value={scale} onValueChange={value=>scale=value} options={[{value:'shared',label:copy.tr('Shared Scale')},{value:'independent',label:copy.tr('Independent Scales')}]}/></div><p class="tp-compare-scale-note" id={scaleId} role="status">{copy.tr(scale==='shared'?'All charts share a vertical scale, so heights can be compared as recorded amounts.':'Each source has its own scale. Compare shapes, not amounts across charts.')}</p>{#if issue}<p class="tp-compare-context">{issue}</p>{/if}
  <div class="tp-compare-trends" data-source-list role="group" aria-label={copy.tr('Daily source trends. Arrow keys browse; Enter or Space opens details.')}>{#each view.sources as source (source.key)}{@const max=trendMaximum(source)}{@const values=source.days.map(day=>valueOf(day,measure))}{@const previous=source.previousDays.map(day=>valueOf(day,measure))}<CompareSourceButton {source} {selected} {onSelect} class="tp-compare-trend-card"><span class="tp-compare-source-name"><ProviderMark {source}/><strong>{source.name}</strong></span><span class="tp-compare-domain">{max===null?copy.tr('Scale Unknown'):max===0?copy.tr('Only Zero Values'):`${(0).toLocaleString(language)}–${copy.format(max,measure)}`}</span><span class="tp-compare-trend-frame" data-scale-max={max??'unknown'}><svg class="tp-compare-trend" viewBox="0 0 240 80" aria-hidden="true"><path d="M6 8H234 M6 39H234 M6 70H234" class="tp-compare-grid-line"/><path d={trendPath(previous,max)} class="tp-compare-prior-line"/><path d={trendPath(values,max)} class="tp-compare-current-line"/>{#each previous as value,at}{#if value!==null}<circle cx={trendX(at)} cy={trendY(value,max)} r="2.6" class="tp-compare-prior-point"/>{/if}{/each}{#each values as value,at}{#if value!==null}<circle cx={trendX(at)} cy={trendY(value,max)} r="1.8" class="tp-compare-current-point"/>{/if}{/each}</svg><span class="tp-compare-time-axis"><span>{copy.tr('Day %@',(1).toLocaleString(language))}</span>{#if view.length>1}<span>{copy.tr('Day %@',view.length.toLocaleString(language))}</span>{/if}</span></span>{@render pairValues(source)}</CompareSourceButton>{/each}</div>
  <p class="tp-chart-note">{copy.tr('Solid lines and filled points are current; dashed lines and hollow points are previous. Periods align by day number, gaps stay unknown, and exact values are period totals.')} {view.length===1?copy.tr('One day is a point, not a trend.'):''} {copy.tr('Arrow keys browse sources. Enter, Space, or a click opens details.')}</p>
 {:else}
  <div class="tp-compare-net"><span class="tp-caption">{copy.tr(water.issue?'Recorded Period Totals':'Current − Previous')}</span><strong>{water.net===null?copy.tr('Difference Unavailable'):deltaText(water.net)}</strong><span class="tp-caption">{water.net===null?water.issue:copy.tr(water.net===0?'Net change is zero; individual sources may still have changed.':'An increase or decrease describes usage, not a good or bad outcome.')}</span></div>
  {#if !water.issue}<div class="tp-compare-waterfall" role="group" aria-label={copy.tr('Waterfall from previous to current total. Arrow keys browse sources; Enter or Space opens details.')}><div class="tp-compare-water-axis" aria-hidden="true"><span>{copy.format(water.ceiling,measure)}</span><span>{water.peak===0?'':copy.format(water.ceiling/2,measure)}</span><span>{(0).toLocaleString(language)}</span></div><div class="tp-compare-water-scroll"><div class="tp-compare-water-steps" style={`--step-count:${water.steps.length}`} data-source-list>{#each water.steps as step,index (step.key)}{#if step.source}<CompareSourceButton source={step.source} {selected} {onSelect} class="tp-compare-water-step" label={copy.tr('%@: change %@ %@. Open model details.',step.name,deltaText(step.delta),copy.unit(measure))}>{@render graphic(step,index)}</CompareSourceButton>{:else}<div class="tp-compare-water-total">{@render graphic(step,index)}</div>{/if}{/each}</div></div></div>{/if}
  {@render periodTotals()}<div class="tp-compare-contribution-head"><span>{copy.tr(water.issue?'Recorded Sources':'Source Contributions')}</span><span>{water.issue?copy.tr('Exact Period Totals'):copy.tr('Change · %@',copy.unit(measure))}</span></div><div class="tp-compare-contributions" data-source-list role="group" aria-label={copy.tr('Source changes. Arrow keys browse; Enter or Space opens details.')}>{#each pairs as {source,delta},index (source.key)}<CompareSourceButton {source} {selected} {onSelect} class="tp-compare-contribution"><span class="tp-compare-source-name"><span class="tp-compare-index">{(index+1).toLocaleString(language,{minimumIntegerDigits:2})}</span><ProviderMark {source}/><strong>{source.name}</strong></span>{#if water.issue}{@render pairValues(source)}{:else}<span class="tp-compare-contribution-value" data-delta={delta}><b>{deltaText(delta!)}</b><small>{copy.tr(delta===0?'No Change':delta!>0?'Increase':'Decrease')}</small></span>{/if}</CompareSourceButton>{/each}</div>
  <p class="tp-chart-note">{copy.tr(water.issue?'The waterfall requires complete records; an unknown difference is never replaced with zero.':'Start at the hollow previous total, add each source’s change, and reach the filled current total. Colors identify sources; zero changes are short lines.')} {copy.tr('Arrow keys browse sources. Enter, Space, or a click opens details.')}</p>
 {/if}
 <p class="tp-compare-sr-only" role="status">{selectedSource?copy.tr('%@ selected. Model details are below the chart.',selectedSource.name):copy.tr('No source is selected.')}</p>
</section>
